// Shared expected results for both runtimes; all examples are fictional.
export const containsAnyCases: { name: string; value: unknown; expected: boolean }[] = [
  { name: 'list: one match', value: ['B', 'A'], expected: true },
  { name: 'list: no match', value: ['B'], expected: false },
  { name: 'empty list', value: [], expected: false },
  { name: 'scalar match', value: 'A', expected: true },
  { name: 'scalar no match', value: 'B', expected: false },
  { name: 'absent', value: undefined, expected: false },
  { name: 'null', value: null, expected: false },
  { name: 'missing reason', value: { __missing__: 'A' }, expected: false },
  { name: 'missing with forged code', value: { __missing__: 'inconnu', code: 'A', label: 'Alpha' }, expected: false },
  { name: 'diagnosis', value: { code: 'A', label: 'Alpha' }, expected: true },
  { name: 'diagnoses', value: [{ code: 'B', label: 'Beta' }, { code: 'A', label: 'Alpha' }], expected: true },
  { name: 'label is not a code', value: { code: 'B', label: 'A' }, expected: false },
  { name: 'exact code, not prefix', value: { code: 'A.1', label: 'Alpha' }, expected: false },
  { name: 'code is not normalized', value: { code: ' A', label: 'Alpha' }, expected: false },
  { name: 'case is exact', value: 'a', expected: false },
  { name: 'JSON text is not decoded', value: '{"code":"A","label":"Alpha"}', expected: false },
  { name: 'numeric code is invalid', value: { code: 1, label: 'Alpha' }, expected: false },
  { name: 'numeric label is invalid', value: { code: 'A', label: 1 }, expected: false },
  { name: 'missing label', value: { code: 'A' }, expected: false },
  { name: 'empty label', value: { code: 'A', label: '' }, expected: false },
  { name: 'unicode whitespace label', value: { code: 'A', label: '\u00a0\u2003\ufeff' }, expected: false },
  { name: 'extra property', value: { code: 'A', label: 'Alpha', extra: true }, expected: false },
  { name: 'partial list invalidates whole', value: [{ code: 'A', label: 'Alpha' }, {}], expected: false },
  { name: 'mixed list', value: ['A', { code: 'B', label: 'Beta' }], expected: false },
  { name: 'null list element', value: ['A', null], expected: false },
  { name: 'nested list', value: [['A']], expected: false },
  { name: 'duplicate diagnoses', value: [{ code: 'A', label: 'Alpha' }, { code: 'A', label: 'Alpha' }], expected: false },
  { name: 'more than 50 diagnoses', value: Array.from({ length: 51 }, (_, i) => ({ code: i === 0 ? 'A' : `B${i}`, label: 'Fictif' })), expected: false },
  { name: 'boolean', value: true, expected: false },
  { name: 'number', value: 1, expected: false },
];

export const invalidContainsAnyConfigs = [undefined, null, [], 'A', [1], [''], ['\u00a0'], ['A', 'A'], [{ code: 'A' }]];
